function preferenceList(rows){if(!rows?.length)return empty('No selections recorded','These preferences will appear when their values are supplied by a configurator.');const max=Math.max(...rows.map(r=>r.count||0),1);return `<div class="breakdown-list">${rows.slice(0,7).map(r=>`<div class="bar-row"><span>${escape(r.name)}</span><span class="bar-track"><span class="bar-fill" style="width:${r.count/max*100}%;background:var(--blue)"></span></span><span class="bar-value" title="${num(r.count)} selections">${pct(r.pct)}</span></div>`).join('')}</div><p class="panel-note">${num(rows.reduce((a,r)=>a+(r.count||0),0))} recorded selections</p>`;}
function renderLeads(){const r=state.report;let leads=r.leads;if(state.leadTab==='newsletter')leads=leads.filter(l=>l.marketing_consent===true);return `<div class="tabbar" role="tablist" aria-label="Lead list"><button class="tab-button ${state.leadTab==='all'?'active':''}" role="tab" aria-selected="${state.leadTab==='all'}" data-action="lead-tab" data-value="all">All leads <span class="faint">${num(r.leads.length)}</span></button><button class="tab-button ${state.leadTab==='newsletter'?'active':''}" role="tab" aria-selected="${state.leadTab==='newsletter'}" data-action="lead-tab" data-value="newsletter">Newsletter subscribers <span class="faint">${num(r.leads.filter(l=>l.marketing_consent===true).length)}</span></button></div>${panel(state.leadTab==='newsletter'?'Newsletter subscribers':'Leads',table(leadColumns(),leads,{caption:state.leadTab==='newsletter'?'Only people whose latest recorded marketing consent is explicitly true.':'Email capture and marketing consent are separate. Open a lead to manage status and notes.'}),{table:true,description:state.leadTab==='newsletter'?'Explicit opt-ins, with their recorded consent evidence.':'Volunteered contacts linked to their anonymous history.',action:makeAction('export-leads',state.leadTab,'↓ Export CSV','button small')})}<div class="grid" style="margin-top:20px">${panel('High-intent visitors',table([{label:'Visitor',render:j=>makeAction(j.lead?'lead':'journey',j.lead?.id||j.visitor_id,escape(j.lead?.email||j.visitor_id))},{label:'Country',key:'country'},{label:'Simulator',key:'category'},{label:'Source',key:'source'},{label:'Intent score',num:true,render:j=>score(j.intentScore)},{label:'Latest activity',render:j=>date(j.lastActivity,true)}],r.journeys.filter(j=>j.intentScore>=60).slice(0,50)),{table:true,description:'Anonymous visitors stay anonymous until they volunteer contact details.'})}</div>`;}
function renderOpenAILegacy(){
 const r=state.report;
 const outcomes=[{label:'Visits',num:true,key:'sessions'},{label:'Visitors',num:true,key:'visitors'},{label:'Configurator starts',num:true,key:'starts'},{label:'Completed',num:true,key:'completed'},{label:'Configurations emailed',num:true,key:'emailed'},{label:'Emails captured',num:true,key:'emails'},{label:'Enquiries',num:true,key:'enquiries'}];
 const campaign=[{label:'Campaign',key:'name'},{label:'Campaign code',key:'campaign_id'},...outcomes];
 const ads=[{label:'Campaign',key:'name'},{label:'Ad group code',key:'ad_group_id'},{label:'Ad code',key:'ad_id'},...outcomes];
 return panel('OpenAI Ads — website results',table(campaign,r.openaiCampaigns||[]),{table:true,description:'Recorded website visits attributed to your ChatGPT paid campaign codes. Uses the current dates and filters; analytics consent and blockers affect coverage. Visits are not billed clicks.'})+
 panel('OpenAI Ads — ad group and ad breakdown',table(ads,r.openaiAds||[]),{table:true,description:'Unrecorded means the code was absent. Historical IDs are recovered only when retained in a recorded landing URL.',action:makeAction('export-openai','','↓ Export OpenAI CSV','button small')})+
 panel('OpenAI spend effectiveness',`<p class="settings-note">Enter actual GBP spend from Ads Manager for exactly the dates and campaigns selected above. Spend is not synced. This calculator is temporary and is not saved. Enquiries are recorded events, not verified sales or qualified leads.</p><form id="openai-cost-form" class="settings-form"><label>Actual spend (£)<input name="spend" type="number" min="0" step="0.01" required></label><button class="button" type="submit">Calculate costs</button><div id="openai-cost-result" role="status"></div></form>`);
}

function renderOpenAI(){
 var r=wiOpenAI();
 var note='<div class="inline-metrics config-metrics">'+[
  ['Tracked landing sessions',r.landingSessions],['Tracked sessions',r.sessions],['Distinct browsers',r.visitors],['Unique click IDs',r.clickIds],['Configurator starts',r.starts],['Software clicks',r.softwareClicks]
 ].map(x=>'<div class="inline-metric"><span>'+escape(x[0])+'</span><strong>'+num(x[1])+'</strong></div>').join('')+'</div>'+
 '<p class="panel-note">Ads Manager clicks and first-party website visitors are different measures. One browser can create several ad clicks; consent refusal, blockers, redirects and failed page loads can also stop a click becoming a tracked website session.</p>';
 return panel('OpenAI Ads — tracking reconciliation',note,{description:'Use these website-side measures when comparing against Ads Manager.'})+renderOpenAILegacy();
}
function renderCampaigns(){const r=state.report;return renderOpenAI()+panel('Campaign performance',table(campaignColumns(),r.campaigns,{caption:'Potential Configured Value is not revenue. Each currency is reported separately.'}),{table:true,description:'Campaign parameters and ref codes are retained together.',action:makeAction('export-campaigns','','↓ Export CSV','button small')})+'<div class="grid" style="margin-top:20px">'+panel('Campaign quality',table([{label:'Campaign',render:c=>makeAction('filter',c.name,escape(c.name),'row-link','data-dimension="campaign"')},{label:'Start rate',num:true,render:c=>pct(rate(c.starts,c.visitors))},{label:'Completion rate',num:true,render:c=>pct(rate(c.completed,c.starts))},{label:'Email capture rate',num:true,render:c=>pct(rate(c.emails,c.completed))},{label:'Enquiry rate',num:true,render:c=>pct(c.conversion)},{label:'Average intent',num:true,render:c=>dec(c.avgIntent)},{label:'Average configured value',num:true,render:c=>values(c.avgValueByCurrency)}],r.campaigns),{table:true,description:'Start = starts ÷ visitors · completion = completed ÷ starts · email = captured ÷ completed · enquiry = enquiries ÷ visitors.'})+'</div><div class="grid two">'+panel('Sources by enquiries',breakdown([...r.sources].sort((a,b)=>b.enquiries-a.enquiries),'source','enquiries','var(--green)'),{description:'Traffic quality, expressed in commercial actions.'})+panel('Simulator commercial performance',simulatorTable(r.categories),{table:true,description:'Use a source or campaign filter to compare the markets it attracts.'})+'</div>';}
function renderJourneys(){return panel('Visitor journeys',table([{label:'Visitor',render:j=>makeAction('journey',j.visitor_id,`${escape(j.lead?.name||j.lead?.email||j.visitor_id)}<span class="row-secondary">${j.lead?escape(j.visitor_id):'Anonymous visitor'}</span>`)},{label:'Country',key:'country'},{label:'Source',key:'source'},{label:'Simulator',key:'category'},{label:'Events',num:true,render:j=>num(j.events?.length)},{label:'Intent',num:true,render:j=>score(j.intentScore)},{label:'Last activity',render:j=>date(j.lastActivity,true)}],state.report.journeys,{caption:'Journeys connect recorded events from the same first-party browser identifier.'}),{table:true,description:'Select any visitor to see their chronological history.'});}
function activeFilterCount(){return Object.entries(state.filters).filter(([key,value])=>!['preset','from','to','compare','query'].includes(key)&&value!=='All').length+(state.filters.query?1:0);}
function resetNonDateFilters(){const {preset,from,to,compare}=state.filters;state.filters={...filterDefaults,preset,from,to,compare};$('#global-search').value='';filterOptions();}
function liveWithoutAdvancedFilters(){const clean={...state.filters,source:'All',campaign:'All',country:'All',device:'All',category:'All',model:'All',configurator:'All',visitorType:'All',identity:'All',status:'All',intent:'All',query:''};return buildReport(state.snapshot,clean,new Date()).live||[];}
function liveCards(rows,overallFallback=false){return `<div class="live-cards">${rows.map(j=>`<article class="live-card"><div class="live-card-top"><span><span class="connection-dot"></span>${escape(j.country||'Unknown country')}</span><span>${escape(human(j.configurator_type||'Website'))}</span></div><h3>${makeAction(overallFallback?'live-journey':'journey',j.visitor_id,escape(j.lead?.email||j.visitor_id))}</h3><p>${escape(j.currentPage||j.events?.at(-1)?.page_url||'Unknown page')}</p><p>${escape(j.category||'Simulator not selected')}${j.simulator_model?' · '+escape(j.simulator_model):''}</p><div class="stat-line"><span>Current step</span><strong>${escape(human(j.lastStep||j.events?.at(-1)?.event_name||'Page view'))}</strong></div><div class="stat-line"><span>Source</span><strong>${escape(j.source||'Unknown')}</strong></div></article>`).join('')}</div>`;}
function renderLive(){const rows=state.report.live||[],filterCount=activeFilterCount(),overall=filterCount?liveWithoutAdvancedFilters():rows,overallFallback=Boolean(filterCount&&!rows.length&&overall.length),displayRows=overallFallback?overall:rows;const filteredNote=filterCount?`<div class="settings-note" style="margin:-8px 0 18px">${num(rows.length)} active ${rows.length===1?'visitor matches':'visitors match'} the current ${filterCount===1?'filter':'filters'}.${rows.length!==overall.length?' The headline shows all active visitors so hidden filters cannot make Live appear empty.':''} ${makeAction('clear-live-filters','','Clear filters','text-button')}</div>`:'';return `<div class="action-row" style="justify-content:space-between;margin-bottom:22px"><div class="live-heading"><span class="live-pulse"></span><span style="font-size:20px;font-weight:550">${num(overall.length)} active ${overall.length===1?'visitor':'visitors'}</span></div><span class="small-text faint">${state.mode==='demo'?'Demonstration snapshot':'Refreshes every 30 seconds'}</span></div>${filteredNote}${displayRows.length?liveCards(displayRows,overallFallback):panel('Active visitors',empty('No visitors active right now','A visitor appears here when their most recent recorded activity is within the past five minutes.'))}`;}
function renderInsights(){const r=state.report;return `<div class="insight-grid">${r.insights.length?r.insights.map(i=>`<div class="insight-card">${insightsList([i],1)}</div>`).join(''):panel('Insights',insightsList([]))}</div><div class="grid" style="margin-top:24px">${panel('Problems & performance',table([{label:'Problem',render:p=>`<span>${escape(human(p.name))}</span><span class="row-secondary">${escape(p.message||'')}</span>`},{label:'Type',render:p=>badge(human(p.type||'error'),p.type==='error'?'red':'amber')},{label:'Page',render:p=>escape(p.page_url)},{label:'Duration',num:true,render:p=>p.duration_ms?`${num(p.duration_ms)} ms`:'—'},{label:'Visitor',render:p=>makeAction('journey',p.visitor_id,escape(p.visitor_id))},{label:'Recorded',render:p=>date(p.timestamp,true)}],r.problems,{emptyTitle:'No problems recorded',emptyDetail:'Captured website errors, failed requests and slow operations will appear here.'}),{table:true,description:'Recorded errors and slow operations in the current population.'})}</div>`;}
function renderSettings(){const settings={...defaultSettings,...state.snapshot.settings,scoring:{...defaultSettings.scoring,...state.snapshot.settings?.scoring},alertThresholds:{...defaultSettings.alertThresholds,...state.snapshot.settings?.alertThresholds}};return `<div class="settings-grid">${panel('Intent scoring',`<p class="settings-note">Each signal contributes once per visitor. Repeated clicks do not inflate intent. High intent begins at 60 points; sales lead at 80.</p><form id="scoring-form" class="settings-form">${Object.entries(settings.scoring).map(([key,value])=>`<div class="settings-row"><label for="score-${attr(key)}">${escape(human(key))}</label><input id="score-${attr(key)}" name="${attr(key)}" type="number" min="0" max="100" step="1" value="${Number(value)||0}" aria-label="Points for ${attr(human(key))}"></div>`).join('')}<button type="submit" class="button primary">Save scoring rules</button></form>`,{description:'A practical measure of demonstrated commercial interest.'})}<div class="grid">${panel('Collection status',`<div class="stat-line"><span>Workspace</span><strong>${state.mode==='demo'?'Demonstration':'Connected reports'}</strong></div><div class="stat-line"><span>Recorded events loaded</span><strong>${num(state.snapshot.events?.length)}</strong></div><div class="stat-line"><span>Last refresh</span><strong>${date(state.lastUpdated,true)}</strong></div><div class="stat-line"><span>Reporting timezone</span><strong>Europe/Madrid</strong></div><div class="stat-line"><span>Session timeout</span><strong>30 minutes inactive</strong></div><p class="settings-note" style="margin-top:15px">This workspace is isolated from the public website. Live tracking starts only after the supplied collector and configurator hooks are deliberately installed. Past visits cannot be reconstructed.</p><div class="code-block">${escape(config.endpoint)}</div>`,{description:'One central endpoint for website and configurator events.'})}${panel('Alerts',`<p class="settings-note">Saved thresholds identify in-dashboard signals. External notification delivery is not connected.</p><form id="alerts-form" class="settings-form"><label class="check-label"><input name="enabled" type="checkbox" ${settings.alertsEnabled?'checked':''}>Enable in-dashboard alert signals</label><div class="settings-row"><label for="traffic-alert">Traffic increase <small>Compared with previous period, %</small></label><input id="traffic-alert" name="trafficIncreasePct" type="number" min="1" max="1000" value="${Number(settings.alertThresholds.trafficIncreasePct)||50}"></div><div class="settings-row"><label for="conversion-alert">Conversion fall <small>Compared with previous period, %</small></label><input id="conversion-alert" name="conversionDropPct" type="number" min="1" max="100" value="${Number(settings.alertThresholds.conversionDropPct)||30}"></div><div class="settings-row"><label for="value-alert">High configuration value <small>Applied within each recorded currency</small></label><input id="value-alert" name="highValue" type="number" min="0" step="1000" value="${Number(settings.alertThresholds.highValue)||100000}"></div><button class="button" type="submit">Save alert settings</button></form>`,{description:'Optional, and disabled by default.'})}${panel('Demonstration',`<p class="settings-note">Explore every report with fictional visitors and contacts. Demo edits stay in this browser and never reach the real database.</p><div class="action-row">${makeAction('demo','','Open demo','button')}${state.mode==='demo'?makeAction('reset-demo','','Reset demo edits','button'):''}</div>`)}${panel('Data retention & attribution',`<p class="settings-note">No automatic analytics deletion is enabled. First-touch attribution stays attached to a visitor; each session retains its latest source and full campaign parameters.</p><p class="settings-note">Newsletter exports require explicit opt-in. Configurations and customer contact details remain separate from anonymous event properties.</p>`)}</div></div>`;}

function render(){if(!state.snapshot)return;try{state.report=buildReport(state.snapshot,state.filters,new Date());}catch(error){$('#content').innerHTML=panel('Report unavailable',empty('We could not calculate this report',error.message));return;}const r=state.report;const liveTotal=activeFilterCount()?liveWithoutAdvancedFilters().length:r.live.length;const item=nav.find(n=>n[0]===state.tab)||nav[0];$('#breadcrumb-page').textContent=item[1];$('#page-title').textContent=item[1];$('#page-eyebrow').textContent=descriptions[state.tab][0];$('#page-description').textContent=descriptions[state.tab][1];$('#primary-nav').innerHTML=nav.map(([key,label,path])=>`<button class="nav-button ${state.tab===key?'active':''}" data-action="nav" data-value="${key}" ${state.tab===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${path}</svg></span>${label}${key==='live'&&liveTotal?`<span class="nav-count">${num(liveTotal)}</span>`:''}</button>`).join('');$('#range-label').textContent=`${r.range?.from||''} — ${r.range?.to||''} · Europe/Madrid`;$('#comparison-label').textContent=state.filters.compare?`Compared with ${r.range?.previousFrom||'previous period'} — ${r.range?.previousTo||''}`:'';$('#content').innerHTML=({overview:renderOverview,traffic:renderTraffic,funnels:renderFunnels,configurators:renderConfigurators,leads:renderLeads,campaigns:renderCampaigns,journeys:renderJourneys,live:renderLive,insights:renderInsights,settings:renderSettings}[state.tab]||renderOverview)();$('#last-updated').textContent=`${state.mode==='demo'?'Demo data · ':''}Updated ${date(state.lastUpdated,true)}`;updateFilterCounts();wireChart();updateBanner();}
function wireChart(){const chart=$('#activity-chart');if(!chart)return;const hover=$('.chart-hover',chart);chart.addEventListener('pointermove',e=>{const rect=chart.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-rect.left-rect.width*.035)/(rect.width*.955))),rows=state.report.daily||[],i=Math.round(ratio*(rows.length-1)),row=rows[i];if(!row)return;const labels={visitors:'Visitors',sessions:'Sessions',pageViews:'Page views',starts:'Starts',completed:'Completed',leads:'Leads',enquiries:'Enquiries'};hover.innerHTML=`<strong>${escape(row.date)}</strong>${state.metrics.map(m=>`<div>${labels[m]} <span style="float:right;margin-left:20px">${num(row[m])}</span></div>`).join('')}`;hover.hidden=false;hover.style.left=`${Math.min(Math.max(0,e.clientX-rect.left+12),rect.width-hover.offsetWidth-8)}px`;hover.style.top='8px';});chart.addEventListener('pointerleave',()=>hover.hidden=true);}
function updateFilterCounts(){const count=activeFilterCount();$('#filter-count').textContent=count;$('#filter-count').hidden=!count;$('#clear-filters').hidden=!count;}
function filterOptions(){const r=buildReport(state.snapshot,{...filterDefaults,preset:'This Year'},new Date());const options=r.options||{};const categories=options.categories||[];$('#category-filter').innerHTML='<option value="All">All simulators</option>'+categories.map(v=>`<option ${state.filters.category===v?'selected':''} value="${attr(v)}">${escape(v)}</option>`).join('');const fields=[['source','Traffic source',options.sources],['campaign','Campaign',options.campaigns],['country','Country',options.countries],['device','Device',options.devices],['model','Simulator model',options.models],['configurator','Configurator',options.configurators],['visitorType','Visitor type',['New','Returning']],['identity','Identity',['Known','Anonymous']],['status','Lead status',options.statuses?.length?options.statuses:statuses],['intent','Intent level',options.intents?.length?options.intents:['Low','Interested','Engaged','High Intent','Sales Lead']]];$('#advanced-filters').innerHTML=fields.map(([key,label,values])=>`<label>${label}<select data-filter="${key}"><option value="All">All</option>${(values||[]).map(v=>`<option value="${attr(v)}" ${state.filters[key]===v?'selected':''}>${escape(v)}</option>`).join('')}</select></label>`).join('');}
function setFilter(dimension,value){state.filters[dimension]=value;const select=dimension==='category'?$('#category-filter'):$(`[data-filter="${dimension}"]`);if(select)select.value=value;state.tab=dimension==='category'?'traffic':dimension==='campaign'?'campaigns':dimension==='source'?'journeys':state.tab;render();closeDrawer();$('#sidebar').classList.remove('open');toast(`Showing ${value}`);}
function openDrawer(title,body,eyebrow='DETAIL'){state.drawerFocus=document.activeElement;$('#drawer-title').textContent=title;$('#drawer-eyebrow').textContent=eyebrow;$('#drawer-content').innerHTML=body;$('#detail-drawer').hidden=false;$('#drawer-backdrop').hidden=false;document.body.style.overflow='hidden';$('#detail-drawer').focus();}
function closeDrawer(){if($('#detail-drawer').hidden)return;$('#detail-drawer').hidden=true;$('#drawer-backdrop').hidden=true;document.body.style.overflow='';if(state.drawerFocus?.isConnected)state.drawerFocus.focus();}
function eventTimeline(events){if(!events?.length)return empty('No recorded journey');return `<ol class="timeline">${[...events].sort((a,b)=>new Date(a.timestamp)-new Date(b.timestamp)).map(e=>`<li><time datetime="${attr(e.timestamp)}">${escape(date(e.timestamp,true))}</time><strong>${escape(human(e.event_name))}</strong><p>${escape(e.page_url||'')}${[e.properties?.simulator_category,e.properties?.simulator_model,e.properties?.screen_type,e.properties?.pixel_pitch,e.properties?.projector_type].filter(Boolean).map(v=>' · '+escape(v)).join('')}</p>${e.properties?.configuration_id?makeAction('configuration',e.properties.configuration_id,escape(e.properties.configuration_id),'text-button'):''}</li>`).join('')}</ol>`;}
function showJourney(id){const j=state.report.journeys.find(j=>j.visitor_id===id);if(!j){toast('This visitor has no activity in the selected report.');return;}openDrawer(j.lead?.email||j.visitor_id,section('Visitor',detailGrid([['Anonymous ID',j.visitor_id],['Country',j.country],['Source',j.source],['Simulator',j.category],['Intent score',j.intentScore],['Latest activity',date(j.lastActivity,true)]]))+(j.lead?`<div class="action-row" style="margin-bottom:25px">${makeAction('lead',j.lead.id,'Open lead record ↗','button small')}</div>`:'')+section('Chronological journey',eventTimeline(j.events)),'VISITOR JOURNEY');}
function showLead(id){const l=state.report.leads.find(l=>l.id===id)||state.snapshot.leads.find(l=>l.id===id);if(!l)return toast('This lead is outside the selected report.');const journeys=state.report.journeys.filter(j=>j.lead?.id===l.id||(l.visitor_ids||[]).includes(j.visitor_id));const configs=state.report.configurations.filter(c=>c.lead_id===l.id||(l.visitor_ids||[]).includes(c.visitor_id));openDrawer(l.name||l.email,section('Contact',detailGrid([['Email',l.email],['Name',l.name],['Company',l.company],['Telephone',l.telephone],['Country',l.country],['First recorded visit',date(l.first_seen,true)],['Last activity',date(l.last_seen,true)]]))+section('Attribution',detailGrid([['First source',l.first_source],['First campaign',l.first_campaign],['Latest source',l.latest_source],['Latest campaign',l.latest_campaign]]))+section('Commercial interest',detailGrid([['Simulator',l.simulator_interest],['Intent score',l.intentScore??l.intent_score],['Configurations',configs.length]]))+section('Lead status & notes',`<form id="lead-edit-form" class="detail-form" data-lead="${attr(l.id)}"><label>Status<select name="status">${statuses.map(s=>`<option ${String(l.status).toUpperCase()===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Notes<textarea name="notes" maxlength="5000" placeholder="Add a useful note for the next conversation…">${escape(l.notes||'')}</textarea></label><div class="action-row"><button class="button primary" type="submit">Save lead</button><span class="small-text faint">${state.mode==='demo'?'Saved in this demo only':'Saved to reporting database'}</span></div></form>`)+section('Marketing consent',detailGrid([['Newsletter',l.marketing_consent===true?'Explicit opt-in':'No current consent'],['Consent recorded',date(l.consent_timestamp,true)],['Wording version',l.consent_text_version],['Source page',l.consent_source]]))+section('Saved configurations',configs.length?configs.map(c=>makeAction('configuration',c.id,`<strong>${escape(c.id)}</strong><p>${escape(c.simulator_model||c.simulator_category||'Not selected')} · ${money(c.estimated_price,c.currency)} · ${date(c.created_at)}</p>`,'config-card')).join(''):empty('No configurations in this period'))+section('Recorded journey',eventTimeline(l.events||journeys.flatMap(j=>j.events))),'LEAD RECORD');}
function showConfiguration(id){const c=state.report.configurations.find(c=>c.id===id)||state.snapshot.configurations.find(c=>c.id===id);if(!c)return toast('This configuration was not found in the loaded data.');const specification=c.configuration_json||c.properties||{};openDrawer(c.id,section('Configuration',detailGrid([['Configurator',human(c.configurator_type)],['Simulator category',c.simulator_category],['Simulator model',c.simulator_model],['Visitor',c.visitor_id],['Created',date(c.created_at,true)],['Emailed',c.emailed?'Yes':'No'],['Potential Configured Value',c.estimated_price===null?'Not quoted':money(c.estimated_price,c.currency)],['Source',c.source],['Campaign',c.campaign]]))+section('Specification',`<pre class="code-block">${escape(JSON.stringify(specification,null,2))}</pre>`)+`<p class="settings-note">Potential Configured Value is an estimate generated by the configurator. It is not sales revenue.</p>${makeAction('journey',c.visitor_id,'Open visitor journey ↗','button small')}`,'SAVED CONFIGURATION');}
function showPage(url){const p=state.report.pages.find(p=>p.url===url);if(!p)return;const listRows=x=>Array.isArray(x)?x.map(v=>typeof v==='string'?{name:v,count:''}:v):Object.entries(x||{}).map(([name,count])=>({name,count}));const smallList=x=>listRows(x).length?listRows(x).map(r=>`<div class="stat-line"><span>${escape(r.name||r.url||r.page||'Unknown')}</span><strong>${r.count===''?'Recorded':num(r.count??r.visitors??r.views)}</strong></div>`).join(''):empty('No navigation recorded');openDrawer(p.title||p.url,section('Page',detailGrid([['URL',p.url],['Visitors',p.visitors],['Returning visitors',p.returning],['Sessions',p.sessions],['Page views',p.views],['Average engagement',duration(p.avgTime)],['Average scroll depth',pct(p.scrollDepth)],['Entry rate',pct(p.entryRate)],['Exit rate',pct(p.exitRate)]]))+section('Previous page',smallList(p.previousPages))+section('Next page',smallList(p.nextPages))+section('Devices',smallList(p.devices))+section('Countries',smallList(p.countries))+section('Sources',smallList(p.sources)),'PAGE ANALYTICS');}
function showDropoff(value){const [type,indexString]=value.split(':');const index=Number(indexString);const rows=state.report.funnels[type]||[];const current=rows[index],previous=rows[index-1];if(!current||!previous)return;const currentIds=new Set(current.sessionIds||[]);const missing=(previous.sessionIds||[]).filter(id=>!currentIds.has(id));const journeys=state.report.journeys.filter(j=>j.events.some(e=>missing.includes(e.session_id)));openDrawer(`${previous.label} → ${current.label}`,`<p class="settings-note">${num(current.lost)} sessions did not reach this step during the selected period. A session is only considered abandoned after 30 minutes without activity; recent sessions may still continue.</p>`+table([{label:'Visitor',render:j=>makeAction('journey',j.visitor_id,escape(j.lead?.email||j.visitor_id))},{label:'Source',key:'source'},{label:'Last activity',render:j=>date(j.lastActivity,true)}],journeys,{emptyTitle:'No matching session detail'}),'FUNNEL DROP-OFF');}
function downloadCSV(rows,columns,name){const cell=value=>{let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv='\uFEFF'+[columns.map(c=>cell(c.label)).join(','),...rows.map(row=>columns.map(c=>cell(typeof c.value==='function'?c.value(row):row[c.value])).join(','))].join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download=`simworx-${name}-${state.report.range?.to||'report'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} ${name} records in the current report.`);}
function exportLeads(type){const rows=state.report.leads.filter(l=>type!=='newsletter'||l.marketing_consent===true);const columns=type==='newsletter'?[['Email','email'],['Name','name'],['Company','company'],['Country','country'],['Signup date','consent_timestamp'],['Simulator interest','simulator_interest'],['Marketing source','first_source']]:[['Email','email'],['Name','name'],['Company','company'],['Telephone','telephone'],['Country','country'],['Simulator interest','simulator_interest'],['Last configuration',l=>state.report.configurations.filter(c=>c.lead_id===l.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]?.id||''],['Lead status','status'],['Intent score',l=>l.intentScore??l.intent_score],['Campaign','latest_campaign'],['Last activity','last_seen']];downloadCSV(rows,columns.map(([label,value])=>({label,value})),type==='newsletter'?'newsletter-subscribers':'leads');}
function saveDemoEdits(){try{localStorage.setItem(config.demoEditsKey,JSON.stringify({settings:state.snapshot.settings,leads:state.snapshot.leads.map(l=>({id:l.id,status:l.status,notes:l.notes}))}));}catch{}}
async function saveSettings(update){const next={...state.snapshot.settings,...update};if(state.mode==='demo'){state.snapshot.settings=next;saveDemoEdits();}else{await api('settings',{settings:next});state.snapshot.settings=next;}render();toast(state.mode==='demo'?'Demo settings saved in this browser.':'Reporting settings saved.');}
async function enterDemo(){state.lastError=null;state.mode='demo';state.token=null;state.expiresAt=null;state.snapshot=demoSnapshot(new Date());try{const edits=JSON.parse(localStorage.getItem(config.demoEditsKey)||'null');if(edits){state.snapshot.settings={...state.snapshot.settings,...edits.settings};for(const lead of state.snapshot.leads){const edit=edits.leads?.find(l=>l.id===lead.id);if(edit)Object.assign(lead,edit);}}}catch{}state.lastUpdated=new Date().toISOString();showApp();banner('Demonstration data — all visitors, contacts and commercial results shown here are fictional.',makeAction('return-login','','Open live reports →','text-button'));filterOptions();render();}
function showApp(){$('#login-screen').hidden=true;$('#app-shell').hidden=false;$('#data-mode').textContent=state.mode==='demo'?'DEMO WORKSPACE':'LIVE DATA';$('#data-mode').classList.toggle('demo',state.mode==='demo');$('#sidebar-status').textContent=state.mode==='demo'?'Demonstration workspace':'Reporting service connected';}
async function loadSnapshot(){const version=++state.requestVersion;$('#refresh').disabled=true;try{const data=await api('snapshot');if(version!==state.requestVersion)return;state.lastError=null;state.snapshot=data.snapshot||data;state.snapshot.events ||= [];state.snapshot.leads ||= [];state.snapshot.configurations ||= [];state.snapshot.settings ||= {};state.snapshot.meta ||= {};state.lastUpdated=new Date().toISOString();showApp();filterOptions();if(!state.snapshot.events.length)banner('Live tracking is connected. Activity will appear here as visitors allow analytics.',makeAction('demo','','Explore demo →','text-button'));else banner('');render();}catch(error){if(!$('#app-shell').hidden){state.lastError=error.message;updateBanner();}else $('#login-error').textContent=`${error.message} You can explore the demonstration while the service is being connected.`;}finally{$('#refresh').disabled=false;}}
async function signOut(remote=true){if(remote&&state.mode!=='demo'&&state.token)try{await api('logout');}catch{}state.requestVersion++;sessionClear();state.token=null;state.expiresAt=null;state.snapshot=null;state.report=null;closeDrawer();$('#login-screen').hidden=false;$('#app-shell').hidden=true;$('#pin').value='';$('#login-error').textContent='';$('#pin').focus();}

$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.currentTarget);button.disabled=true;$('#login-error').textContent='';try{const result=await api('login',{pin:$('#pin').value});state.mode='live';state.token=result.token;state.expiresAt=result.expires_at;sessionSave();await loadSnapshot();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}});
$('#demo-login').addEventListener('click',enterDemo);
$('#logout').addEventListener('click',()=>signOut());
$('#refresh').addEventListener('click',()=>state.mode==='demo'?(state.lastUpdated=new Date().toISOString(),render(),toast('Demonstration refreshed.')):loadSnapshot());
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#filters-toggle').addEventListener('click',()=>{const expanded=$('#advanced-filters').hidden;$('#advanced-filters').hidden=!expanded;$('#filters-toggle').setAttribute('aria-expanded',String(expanded));});
$('#clear-filters').addEventListener('click',()=>{resetNonDateFilters();render();});
$('#date-preset').addEventListener('change',e=>{state.filters.preset=e.target.value;$('#custom-dates').hidden=e.target.value!=='Custom Date Range';if(!$('#custom-dates').hidden){if(!$('#date-from').value)$('#date-from').value=state.report.range.from;if(!$('#date-to').value)$('#date-to').value=state.report.range.to;state.filters.from=$('#date-from').value;state.filters.to=$('#date-to').value;}render();});
$('#apply-dates').addEventListener('click',()=>{const from=$('#date-from').value,to=$('#date-to').value;if(!from||!to||from>to){$('#date-error').textContent='Choose a valid start and end date.';return;}$('#date-error').textContent='';state.filters.from=from;state.filters.to=to;render();});
$('#compare').addEventListener('change',e=>{state.filters.compare=e.target.checked;render();});
$('#category-filter').addEventListener('change',e=>{state.filters.category=e.target.value;render();});
let searchTimer;$('#global-search').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.filters.query=e.target.value.trim();render();},250);});
$('#advanced-filters').addEventListener('change',e=>{if(e.target.matches('[data-filter]')){state.filters[e.target.dataset.filter]=e.target.value;render();}});
$('#drawer-close').addEventListener('click',closeDrawer);$('#drawer-backdrop').addEventListener('click',closeDrawer);
document.addEventListener('keydown',e=>{if(!$('#detail-drawer').hidden){if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const focusable=$$('button,input,select,textarea,a[href],[tabindex="0"]',$('#detail-drawer')).filter(el=>!el.disabled&&!el.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#detail-drawer'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}else if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('change',e=>{if(e.target.matches('[data-chart-metric]')){const metric=e.target.dataset.chartMetric;if(e.target.checked)state.metrics.push(metric);else state.metrics=state.metrics.filter(x=>x!==metric);if(!state.metrics.length)state.metrics=['visitors'];render();}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,value,dimension}=target.dataset;try{if(action==='nav'){state.tab=value;closeDrawer();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}else if(action==='filter')setFilter(dimension,value);else if(action==='lead')showLead(value);else if(action==='journey')showJourney(value);else if(action==='configuration')showConfiguration(value);else if(action==='page')showPage(value);else if(action==='dropoff')showDropoff(value);else if(action==='configurator'){state.tab='configurators';state.configuratorTab=value;render();}else if(action==='configurator-tab'){state.configuratorTab=value;render();}else if(action==='clear-live-filters'){resetNonDateFilters();render();}else if(action==='live-journey'){resetNonDateFilters();render();showJourney(value);}else if(action==='lead-tab'){state.leadTab=value;render();}else if(action==='export-leads')exportLeads(value);else if(action==='export-campaigns')downloadCSV(state.report.campaigns,[{label:'Campaign',value:'name'},{label:'Visitors',value:'visitors'},{label:'Starts',value:'starts'},{label:'Completed',value:'completed'},{label:'Emails',value:'emails'},{label:'Enquiries',value:'enquiries'},{label:'Enquiry rate (%)',value:'conversion'},{label:'Configured value by currency',value:r=>JSON.stringify(r.valueByCurrency)}],'campaigns');else if(action==='demo')await enterDemo();else if(action==='return-login')await signOut(false);else if(action==='reset-demo'){try{localStorage.removeItem(config.demoEditsKey);}catch{}await enterDemo();toast('Demonstration edits reset.');}else if(action==='insight'){const insight=state.report.insights.find(i=>i.id===value);if(insight){state.tab=insight.tab||'insights';Object.assign(state.filters,insight.filter||{});filterOptions();render();}}}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{if(!['lead-edit-form','scoring-form','alerts-form'].includes(e.target.id))return;e.preventDefault();const button=$('button[type=submit]',e.target),form=new FormData(e.target);button.disabled=true;try{if(e.target.id==='lead-edit-form'){const id=e.target.dataset.lead,update={status:String(form.get('status')),notes:String(form.get('notes'))};if(state.mode!=='demo')await api('update_lead',{id,...update});const lead=state.snapshot.leads.find(l=>l.id===id);if(lead)Object.assign(lead,update);if(state.mode==='demo')saveDemoEdits();render();toast(state.mode==='demo'?'Lead saved in this demo only.':'Lead updated.');}else if(e.target.id==='scoring-form'){const scoring=Object.fromEntries([...form.entries()].map(([k,v])=>[k,Math.max(0,Math.min(100,Number(v)||0))]));await saveSettings({scoring});}else{await saveSettings({alertsEnabled:form.get('enabled')==='on',alertThresholds:{trafficIncreasePct:Number(form.get('trafficIncreasePct')),conversionDropPct:Number(form.get('conversionDropPct')),highValue:Number(form.get('highValue'))}});}}catch(error){toast(error.message);}finally{button.disabled=false;}});
setInterval(()=>{if($('#app-shell').hidden)return;if(state.mode!=='demo'&&state.expiresAt&&new Date(state.expiresAt)<=new Date()){signOut(false);$('#login-error').textContent='Your reporting session expired. Enter the PIN to continue.';return;}if(state.mode==='demo')render();else loadSnapshot();},config.refreshInterval);
(async()=>{if(new URLSearchParams(location.search).get('demo')==='1'){await enterDemo();return;}try{const saved=JSON.parse(sessionStorage.getItem(config.sessionKey)||'null');if(saved?.token&&new Date(saved.expires_at)>new Date()){state.token=saved.token;state.expiresAt=saved.expires_at;await loadSnapshot();}else sessionClear();}catch{sessionClear();}})();

// Report-only calculator: never estimates billed clicks or reads advertising credentials.
document.addEventListener('submit',e=>{
 if(e.target.id!=='openai-cost-form')return;
 e.preventDefault();const spend=Number(new FormData(e.target).get('spend'));
 if(!Number.isFinite(spend)||spend<0)return;
 const r=state.report.openaiTotals||{};
 $('#openai-cost-result').innerHTML=[['Recorded visit',r.sessions],['Configurator start',r.starts],['Configuration emailed',r.emailed],['Email captured',r.emails],['Enquiry',r.enquiries]].map(([label,n])=>`<div class="stat-line"><span>Cost per ${label.toLowerCase()}</span><strong>${n?new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:2,maximumFractionDigits:2}).format(spend/n):'— (no recorded outcomes)'}</strong></div>`).join('');
});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="export-openai"]'))downloadCSV(state.report.openaiAds||[],['name','campaign_id','ad_group_id','ad_id','sessions','visitors','starts','completed','emailed','emails','enquiries'].map(key=>({label:human(key),value:key})),'openai-ad-results');});

document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action="export-configurator-contacts"]');if(!target)return;
 const rows=(state.report.configuratorContacts||[]).filter(r=>r.configurator_type===target.dataset.value);
 downloadCSV(rows,[['Email','email'],['Name','name'],['Company','company'],['Telephone','telephone'],['Country','country'],['Configurator','configurator_type'],['First recorded','first_seen'],['Last activity','last_seen'],['Source','source'],['Configuration','configuration_id']].map(([label,value])=>({label,value})).concat([{label:'Requested actions',value:r=>r.actions.join('; ')},{label:'Recorded outcomes',value:r=>r.outcomes.join('; ')}]),target.dataset.value+'-configurator-contacts');
});
